import React from 'react';
import { useFollow } from '../hooks/useFollow';

export default function FollowButton({ currentUserId, targetUserId, size = 'md' }) {
  const { following, loading, toggle } = useFollow(currentUserId, targetUserId);

  // Don't render if same user
  if (!currentUserId || !targetUserId || currentUserId === targetUserId) return null;

  const sizes = {
    sm: { padding: '4px 12px', fontSize: '12px' },
    md: { padding: '6px 18px', fontSize: '14px' },
    lg: { padding: '8px 24px', fontSize: '15px' }
  };

  return (
    <button
      onClick={(e) => { e.stopPropagation(); toggle(); }}
      disabled={loading}
      style={{
        ...sizes[size],
        borderRadius: '20px',
        border: following ? '1px solid var(--border)' : 'none',
        background: following ? 'transparent' : 'var(--accent)',
        color: following ? 'var(--text-secondary)' : '#fff',
        fontWeight: '600',
        cursor: loading ? 'not-allowed' : 'pointer',
        opacity: loading ? 0.6 : 1,
        transition: 'all 0.2s ease',
        whiteSpace: 'nowrap'
      }}
      onMouseEnter={e => {
        if (following) {
          e.target.textContent = 'Unfollow';
          e.target.style.borderColor = '#ef4444';
          e.target.style.color = '#ef4444';
        }
      }}
      onMouseLeave={e => {
        if (following) {
          e.target.textContent = 'Following';
          e.target.style.borderColor = 'var(--border)';
          e.target.style.color = 'var(--text-secondary)';
        }
      }}
    >
      {loading ? '...' : following ? 'Following' : 'Follow'}
    </button>
  );
}
